<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class MethodicalControlController extends Controller{
private function view(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('methodical_head')||$r->user()->canDo('methodical.view')||$r->user()->canDo('methodical.manage'),403);}
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('methodical_head')||$r->user()->canDo('methodical.manage'),403);}
public function programs(Request $r){$this->view($r);$p=$r->attributes->get('academic_period');$rows=DB::table('teaching_load_plans as l')->join('study_groups as g','g.id','=','l.study_group_id')->join('subjects as s','s.id','=','l.subject_id')->leftJoin('teachers as t','t.id','=','l.teacher_id')->leftJoin('curriculum_plans as cp',function($j)use($p){$j->on('cp.study_group_id','=','l.study_group_id')->on('cp.subject_id','=','l.subject_id')->on('cp.teacher_id','=','l.teacher_id')->where('cp.academic_period_id',$p->id);})->where('l.academic_period_id',$p->id)->select('l.*','g.name as group_name','s.name as subject_name','t.last_name','t.first_name','cp.id as curriculum_id','cp.approval_status','cp.version')->orderBy('g.name')->orderBy('s.name')->get();foreach($rows as $x){$x->topics=$x->curriculum_id?DB::table('curriculum_topics')->where('curriculum_plan_id',$x->curriculum_id)->count():0;$x->hours=$x->curriculum_id?(float)DB::table('curriculum_topics')->where('curriculum_plan_id',$x->curriculum_id)->sum('planned_hours'):0;$x->state=!$x->curriculum_id?'missing':($x->topics===0?'no_ktp':($x->approval_status!=='approved'?'not_approved':'ready'));}return view('methodical.program-control',compact('rows'));}
public function plans(Request $r){$this->view($r);$p=$r->attributes->get('academic_period');$teachers=DB::table('teachers')->where('active',1)->orderBy('last_name')->get();$plans=DB::table('teacher_methodical_plans as p')->join('teachers as t','t.id','=','p.teacher_id')->where('p.academic_period_id',$p->id)->select('p.*',DB::raw("trim(coalesce(t.last_name,'') || ' ' || coalesce(t.first_name,'') || ' ' || coalesce(t.middle_name,'')) as full_name"))->get();return view('methodical.teacher-plans',compact('teachers','plans'));}
public function planStore(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['teacher_id'=>'required|exists:teachers,id','goal'=>'nullable|string|max:10000','self_education_topic'=>'nullable|string|max:5000']);DB::table('teacher_methodical_plans')->updateOrInsert(['academic_period_id'=>$p->id,'teacher_id'=>$d['teacher_id']],['goal'=>$d['goal']??null,'self_education_topic'=>$d['self_education_topic']??null,'status'=>'draft','updated_at'=>now(),'created_at'=>now()]);return back();}
public function portfolio(Request $r){$this->view($r);$rows=DB::table('teacher_portfolio_items as i')->join('teachers as t','t.id','=','i.teacher_id')->select('i.*',DB::raw("trim(coalesce(t.last_name,'') || ' ' || coalesce(t.first_name,'') || ' ' || coalesce(t.middle_name,'')) as full_name"))->orderByDesc('i.item_date')->get();$teachers=DB::table('teachers')->where('active',1)->orderBy('last_name')->get();return view('methodical.portfolio',compact('rows','teachers'));}
public function portfolioStore(Request $r){$this->manage($r);$d=$r->validate(['teacher_id'=>'required|exists:teachers,id','type'=>'required|in:publication,competition,conference,methodical_work,award,project','title'=>'required|string|max:500','item_date'=>'nullable|date','level'=>'nullable|string|max:100','result'=>'nullable|string|max:500','reference'=>'nullable|string|max:1000','description'=>'nullable|string|max:5000']);DB::table('teacher_portfolio_items')->insert($d+['created_at'=>now(),'updated_at'=>now()]);return back();}
public function attestation(Request $r){$this->view($r);$rows=DB::table('teacher_attestation_schedule as a')->join('teachers as t','t.id','=','a.teacher_id')->select('a.*',DB::raw("trim(coalesce(t.last_name,'') || ' ' || coalesce(t.first_name,'') || ' ' || coalesce(t.middle_name,'')) as full_name"))->orderBy('a.planned_on')->get();$teachers=DB::table('teachers')->where('active',1)->orderBy('last_name')->get();return view('methodical.attestation',compact('rows','teachers'));}
public function attestationStore(Request $r){$this->manage($r);$d=$r->validate(['teacher_id'=>'required|exists:teachers,id','category'=>'nullable|string|max:100','previous_on'=>'nullable|date','planned_on'=>'required|date','status'=>'required|in:planned,documents,submitted,passed,postponed','note'=>'nullable|string|max:5000']);DB::table('teacher_attestation_schedule')->insert($d+['created_at'=>now(),'updated_at'=>now()]);return back();}
}